// HasListing applies the HasEdge predicate on the "listing" edge.
func HasListing() predicate.ListingTerms {
	return predicate.ListingTerms(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, ListingTable, ListingColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasListingWith applies the HasEdge predicate on the "listing" edge with a given conditions (other predicates).
func HasListingWith(preds ...predicate.Listing) predicate.ListingTerms {
	return predicate.ListingTerms(func(s *sql.Selector) {
		step := newListingStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ListingTerms) predicate.ListingTerms {
	return predicate.ListingTerms(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ListingTerms) predicate.ListingTerms {
	return predicate.ListingTerms(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ListingTerms) predicate.ListingTerms {
	return predicate.ListingTerms(sql.NotPredicates(p))
}
